-- 自动任务表建表语句
CREATE TABLE `AUTO_TASK` (
 `id` VARCHAR(64) NOT NULL COMMENT '任务标识',
 `master_id` VARCHAR(64) COMMENT '宿主机ID',
 `master_ip` VARCHAR(64) COMMENT '宿主机IP',
 `server_id` VARCHAR(64) COMMENT '服务器ID',
 `server_ip` VARCHAR(64) COMMENT '服务器IP',
 `product_type` INT COMMENT '产品类型: 1 云服务器',
 `task_type` VARCHAR(32) COMMENT '任务类型: 创建 续费 重启 停止 升级 重建 删除',
 `execute_time` VARCHAR(32) COMMENT '执行时间',
 `task_status` INT COMMENT '任务状态: 1:待执行 2:执行中 3:执行完成 -1:执行失败',
 `task_desc` VARCHAR(255) COMMENT '任务描述',
 `platform` VARCHAR(1) COMMENT '操作平台: B 管理员操作, C 会员操作',
 `create_user` VARCHAR(64) COMMENT '创建人',
 `execute_result` VARCHAR(512) COMMENT '执行结果',
 `create_time` DATETIME COMMENT '创建时间',
 `update_time` DATETIME COMMENT '更新时间',
 `params` TEXT COMMENT '任务参数JSON',
 `retry_count` INT DEFAULT 0 COMMENT '重试次数',
 `max_retry` INT DEFAULT 3 COMMENT '最大重试次数',
 `start_time` DATETIME COMMENT '开始处理时间',
 `end_time` DATETIME COMMENT '结束处理时间',
 `next_retry_time` DATETIME COMMENT '下次重试时间',
 `timeout_time` DATETIME COMMENT '任务超时时间',
 PRIMARY KEY (`id`)
) ENGINE=InnoDB COMMENT='自动任务表';

-- 自动任务执行日志建表语句

CREATE TABLE `BUSINESS_TASK_EXECUTION_LOG` (
    `id` varchar(60)  NOT NULL COMMENT '主键',
    `task_id` varchar(60)  NOT NULL COMMENT '任务ID',
    `server_id` varchar(60)  DEFAULT NULL COMMENT '服务器ID',
    `task_type` varchar(100)  NOT NULL COMMENT '任务类型',
    `start_time` datetime DEFAULT NULL COMMENT '执行开始时间',
    `end_time` datetime DEFAULT NULL COMMENT '执行结束时间',
    `duration` bigint DEFAULT NULL COMMENT '执行耗时(毫秒)',
    `status` varchar(20)  NOT NULL COMMENT '执行状态: SUCCESS-成功, FAILED-失败',
    `result_detail` text  COMMENT '执行结果详情',
    `error_message` text  COMMENT '错误信息',
    `create_time` datetime DEFAULT NULL COMMENT '创建时间',
    `update_time` datetime DEFAULT NULL COMMENT '更新时间',
    PRIMARY KEY (`id`)
) ENGINE=InnoDB COMMENT='任务执行日志表';

CREATE TABLE `esc_callback_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `callback_type` varchar(50)  NOT NULL COMMENT '回调类型',
  `callback_param` varchar(255)  NULL DEFAULT NULL COMMENT '回调参数',
  `action` varchar(50)  NOT NULL COMMENT '回调动作',
  `request_data` text  NULL COMMENT '请求参数',
  `response_data` text  NULL COMMENT '响应结果',
  `callback_time` datetime NOT NULL COMMENT '回调时间',
  `server_id` varchar(50)  NULL DEFAULT NULL COMMENT '服务器ID',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0-失败，1-成功）',
  `error_msg` text  NULL COMMENT '错误信息',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_flag` varchar(255)  NULL DEFAULT NULL COMMENT '删除标记',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_callback_time`(`callback_time` ASC) USING BTREE,
  INDEX `idx_server_id`(`server_id` ASC) USING BTREE,
  INDEX `idx_action`(`action` ASC) USING BTREE
) ENGINE = InnoDB COMMENT = 'ESC回调日志表' ROW_FORMAT = Dynamic;


ALTER TABLE `business_server`
    MODIFY COLUMN `AVAILABLE_ID` varchar(60)  NULL DEFAULT NULL COMMENT '可用区域ID' AFTER `HOST_NAME`;

ALTER TABLE `business_server`
    ADD PRIMARY KEY (`ID`);


ALTER TABLE `server_local_line`
    CHANGE COLUMN `HARD_DISK_MIN_SIZE` `DATA_DISK_MIN_SIZE` int NOT NULL COMMENT '每块最小' AFTER `SNAP_OPEN_MAX`,
    CHANGE COLUMN `HARD_DISK_MAX_SIZE` `DATA_DISK_MAX_SIZE` int NOT NULL COMMENT '每块最大' AFTER `DATA_DISK_MIN_SIZE`,
    CHANGE COLUMN `HARD_DISK_STEP` `DATA_DISK_STEP` int NOT NULL COMMENT '磁盘大小必须是G的倍数' AFTER `DATA_DISK_MAX_SIZE`,
    CHANGE COLUMN `HARD_DISK_DAY_PRICE` `DATA_DISK_DAY_PRICE` decimal(10, 2) NOT NULL COMMENT '磁盘价格（每GB）日价格' AFTER `DEFENSE_FREE_SIZE`,
    CHANGE COLUMN `HARD_DISK_PRICE` `DATA_DISK_PRICE` decimal(10, 2) NOT NULL COMMENT '磁盘价格（每GB）' AFTER `DATA_DISK_DAY_PRICE`,
    ADD COLUMN `SYSTEM_DISK_MIN_SIZE` int NULL DEFAULT NULL COMMENT '系统盘最小' AFTER `UPDATE_USER`,
    ADD COLUMN `SYSTEM_DISK_MAX_SIZE` int NULL COMMENT '系统盘最大' AFTER `SYSTEM_DISK_MIN_SIZE`,
    ADD COLUMN `SYSTEM_DISK_FREE_SIZE` int NULL COMMENT '系统盘赠送大小' AFTER `SYSTEM_DISK_MAX_SIZE`,
    ADD COLUMN `SYSTEM_DISK_DAY_PRICE` decimal(10, 2) NULL COMMENT '系统盘/日单价' AFTER `SYSTEM_DISK_FREE_SIZE`,
    ADD COLUMN `SYSTEM_DISK_MONTH_PRICE` decimal(10, 2) NULL COMMENT '系统盘/月单价' AFTER `SYSTEM_DISK_DAY_PRICE`,
    ADD COLUMN `SYSTEM_DISK_STEP` int NULL COMMENT '系统盘大小必须是G的倍数' AFTER `SYSTEM_DISK_MONTH_PRICE`;


