-- 折扣模板表
CREATE TABLE DISCOUNT_TEMPLATE (
   ID varchar(32) NOT NULL COMMENT '主键ID',
   TEMPLATE_NAME varchar(100) NOT NULL COMMENT '模板名称',
   TEMPLATE_DESCRIPTION varchar(500) DEFAULT NULL COMMENT '模板描述',
   STATUS tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态: 0-禁用 1-启用',
   USE_LIMIT int DEFAULT 0 COMMENT '使用次数限制: 0表示无限制',
   START_TIME datetime DEFAULT NULL COMMENT '开始时间',
   END_TIME datetime DEFAULT NULL COMMENT '结束时间',
   `DELETE_FLAG` varchar(255)  DEFAULT NULL COMMENT '删除标志',
   `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
   `CREATE_USER` varchar(20)  DEFAULT NULL COMMENT '创建用户',
   `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
   `UPDATE_USER` varchar(20)  DEFAULT NULL COMMENT '修改用户',
   PRIMARY KEY (ID)
) ENGINE=InnoDB COMMENT='折扣模板表';

-- 折扣详情表（会员组对应折扣）
CREATE TABLE DISCOUNT_DETAIL (
     ID varchar(32) NOT NULL COMMENT '主键ID',
     TEMPLATE_ID varchar(32) NOT NULL COMMENT '折扣模板ID',
     GROUP_ID int NOT NULL COMMENT '会员组ID',
     GROUP_NAME varchar(100) NOT NULL COMMENT '会员组名称',
     DISCOUNT_VALUE decimal(10,2) NOT NULL COMMENT '折扣值: 百分比(如0.1表示10%)',
     USE_LIMIT int DEFAULT 0 COMMENT '使用次数限制: 0表示无限制',
     `DELETE_FLAG` varchar(255)  DEFAULT NULL COMMENT '删除标志',
     `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
     `CREATE_USER` varchar(20)  DEFAULT NULL COMMENT '创建用户',
     `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
     `UPDATE_USER` varchar(20)  DEFAULT NULL COMMENT '修改用户',
     PRIMARY KEY (ID),
     KEY IDX_TEMPLATE_ID (TEMPLATE_ID),
     KEY IDX_GROUP_ID (GROUP_ID)
) ENGINE=InnoDB COMMENT='折扣详情表（会员组对应折扣）';

