UPDATE server_local_line
SET AUTO_DNS = CONCAT('["', REPLACE(AUTO_DNS, ' ', '","'), '"]')
WHERE AUTO_DNS IS NOT NULL
  AND AUTO_DNS != ''
  AND AUTO_DNS NOT LIKE '[%';


-- 通用 SQL（适用于大多数数据库）
UPDATE business_server
SET data_disks = CONCAT('[', REPLACE(data_disks, ' ', ''), ']')
WHERE data_disks IS NOT NULL
  AND data_disks != ''
  AND data_disks NOT LIKE '[%]'
  AND data_disks NOT LIKE '%[^0-9,]%';

DROP TABLE `sys_resource`;
CREATE TABLE `sys_resource` (
    `ID` varchar(20)  NOT NULL,
    `PARENT_ID` varchar(255)  DEFAULT NULL COMMENT '父id',
    `TITLE` varchar(255)  DEFAULT NULL COMMENT '标题',
    `NAME` varchar(255)  DEFAULT NULL COMMENT '别名',
    `CODE` varchar(255)  DEFAULT NULL COMMENT '编码',
    `CATEGORY` varchar(255)  DEFAULT NULL COMMENT '分类',
    `MODULE` varchar(255)  DEFAULT NULL COMMENT '模块',
    `MENU_TYPE` varchar(255)  DEFAULT NULL COMMENT '菜单类型',
    `PATH` text  COMMENT '路径',
    `COMPONENT` varchar(255)  DEFAULT NULL COMMENT '组件',
    `ICON` varchar(255)  DEFAULT NULL COMMENT '图标',
    `COLOR` varchar(255)  DEFAULT NULL COMMENT '颜色',
    `VISIBLE` varchar(255)  DEFAULT NULL COMMENT '是否可见',
    `SORT_CODE` int DEFAULT NULL COMMENT '排序码',
    `EXT_JSON` longtext  COMMENT '扩展信息',
    `DELETE_FLAG` varchar(255)  DEFAULT NULL COMMENT '删除标志',
    `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
    `CREATE_USER` varchar(20)  DEFAULT NULL COMMENT '创建用户',
    `UPDATE_TIME` datetime DEFAULT NULL COMMENT '修改时间',
    `UPDATE_USER` varchar(20)  DEFAULT NULL COMMENT '修改用户',
    PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC COMMENT='资源';



DROP TABLE `sys_relation`;

CREATE TABLE `sys_relation` (
                                `ID` varchar(20)  NOT NULL,
                                `OBJECT_ID` varchar(255)  DEFAULT NULL COMMENT '对象ID',
                                `TARGET_ID` varchar(255)  DEFAULT NULL COMMENT '目标ID',
                                `CATEGORY` varchar(255)  DEFAULT NULL COMMENT '分类',
                                `EXT_JSON` longtext  COMMENT '扩展信息',
                                PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC COMMENT='关系';





