SELECT CONCAT('1965688908637294', LPAD(ROW_NUMBER() OVER (ORDER BY ID), 3, '0')) AS ID,
       `ORDER_NO`,
       ID AS SERVER_ID,
       `HOST_NAME`
FROM `business_server`
WHERE `ORDER_NO` IS NOT NULL;

