ALTER TABLE `order_server_config`
    CHANGE COLUMN `SYSTEM_VERSION_ID` `SYSTEM_ID` varchar(255)  NULL DEFAULT NULL COMMENT '系统版本ID' AFTER `SYSTEM_CLASS_NAME`,
    CHANGE COLUMN `SYSTEM_VERSION_NAME` `SYSTEM_NAME` varchar(255)  NULL DEFAULT NULL COMMENT '系统版本名称' AFTER `SYSTEM_ID`;


UPDATE order_server_config osc
    JOIN orders o ON osc.ORDER_NO = o.ORDER_NO
    SET osc.TOTAL_PRICE = o.TOTAL_PRICE,
        osc.PAY_PRICE = o.PAY_PRICE,
        osc.UNIT = 'm',
        osc.RENEW_PRICE = o.PAY_PRICE;


UPDATE order_server_config osc
    JOIN orders o ON osc.ORDER_NO = o.ORDER_NO
    SET osc.TOTAL_PRICE = o.TOTAL_PRICE,
        osc.PAY_PRICE = o.PAY_PRICE,
        osc.UNIT = 'm',
        osc.RENEW_PRICE = o.PAY_PRICE,
        osc.CORE_DAY_PRICE = osc.CORE_MONTH_PRICE / 31 ,
        osc.SYSTEM_DISK_DAY_PRICE = osc.CORE_MONTH_PRICE / 31,
        osc.SYSTEM_DISK_DAY_PRICE = osc.CORE_MONTH_PRICE / 31,
        osc.DATA_DISKS_DAY_PRICE = osc.DATA_DISKS_MONTH_PRICE / 31,
        osc.BANDWIDTH_DAY_PRICE = osc.BANDWIDTH_MONTH_PRICE / 31,
        osc.DEFENSE_DAY_PRICE = osc.DEFENSE_MONTH_PRICE / 31;

UPDATE business_server SET SYSTEM_DISK = 30;
UPDATE order_server_config SET SYSTEM_DISK = 30, SYSTEM_DISK_DAY_PRICE= 0, SYSTEM_DISK_MONTH_PRICE= 0, SYSTEM_DISK_FREE_SIZE = 30;
UPDATE orders SET BILLING_MODE = 1;

UPDATE orders SET UPGRADE_ITEM = NULL WHERE ORDER_TYPE = 3;


